select c.*, e.data_transacao, e.valor_m2 nominal,e.valor_m2*exp((select ln_mediana from ref)-i.ln_mediana) corrigido,
exp((select ln_mediana from ref)-i.ln_mediana) fator
from cinto c join public.itbi_escrituras e on translate(upper(e.bairro),'ÁÀÂÃÉÊÍÓÔÕÚÜÇ','AAAAEEIOOOUUC')=c.bairro and e.tipologia=c.tipologia
join public.itbi_price_index i on i.trimestre=date_trunc('quarter',e.data_transacao)::date
where ((e.uso='Residencial' and c.tipologia in ('Apartamento','Casa')) or (e.uso='Comercial' and c.tipologia='Comercial')) and (e.aceita or e.motivo_rejeicao='fora_do_cinto') and e.data_transacao>=current_date-interval '12 months')
select bairro,tipologia,piso,teto,janela,amostra,count(*) n,
count(*) filter(where nominal<piso) baixo_nominal,count(*) filter(where nominal>teto) alto_nominal,
count(*) filter(where corrigido<piso) baixo_corrigido,count(*) filter(where corrigido>teto) alto_corrigido,
round(100.0*avg((nominal<piso or nominal>teto)::int),2) pct_nominal,
round(100.0*avg((corrigido<piso or corrigido>teto)::int),2) pct_corrigido
from base group by 1,2,3,4,5,6 order by pct_corrigido desc;